#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <memory>
#include "parsers.hpp"
#include "LowerTriMatrix.hpp"
#include "Solver.hpp"
#include "TrivialSolver.hpp"
#include "PheremoneMatrix.hpp"

// first: bash build-TSPsolver.sh
// second: ./build/TSPsolver <instance_path> <output_path> [-m <algorithm>]
// for example : 
// ./build/TSPsolver pa561.tsp.gz pa561.tsp.tour -m trivial




// parts of this code (lines 17 - 69) was generated by Google Gemini 3.1 Pro on 18/10/26 

int main(int argc, char* argv[]) {
    // Parsing
    if (argc < 3) {
        std::cout << "Usage: ./TSPsolver <instance_path> <output_path> [-m <algorithm>]\n";
        return 1;
    }

    // map arguments
    std::string instance_path = argv[1];
    std::string output_path = argv[2];
    std::string method = "trivial";

    // Loop to check for -m
    for (int i = 3; i < argc; ++i) {
        std::string arg = argv[i];
        if (arg == "-m" && i + 1 < argc) {
            method = argv[i + 1];
        }
    }

    // File Type Detection
    std::string file_format = "unknown";
    LowerTriParser dummy_parser(instance_path); 
    
    for (const std::string& line : dummy_parser.read_lines()) {
        if (line.find("NODE_COORD_SECTION") != std::string::npos) {
            file_format = "coord";
            break;
        }
        if (line.find("EDGE_WEIGHT_SECTION") != std::string::npos) {
            file_format = "lower-tri";
            break;
        }
    }

    // call the correct parser
    int dimension = 0;
    std::vector<double> flat_weights;

    if (file_format == "coord") {
        CoordParser parser(instance_path);
        auto data = parser.parse();
        dimension = data.first;
        flat_weights = data.second;
    } else if (file_format == "lower-tri") {
        LowerTriParser parser(instance_path);
        auto data = parser.parse();
        dimension = data.first;
        flat_weights = data.second;
    } else {
        std::cout << "Error: bad file format for " << instance_path << "\n";
        return 1;
    }

    // Instantiate the new matrix object using the parsed data
    LowerTriMatrix matrix(dimension, flat_weights);
    std::vector<int> tour;

    // Run the algorithm
    std::unique_ptr<Solver> solver;
    if (method == "trivial") {
        TrivialSolver solver;
        tour = solver.solve(matrix);
    } 
    // add next algo here
    else {
        std::cout << "Error: Algorithm '" << method << "' doesnt exist.\n";
        return 1;
    }

    // write the output
    std::ofstream out_f(output_path);

    

    // Extract filename without extension
    size_t last_slash = instance_path.find_last_of("/\\");
    std::string filename = (last_slash == std::string::npos) ? instance_path : instance_path.substr(last_slash + 1);
    size_t last_dot = filename.find_last_of('.');
    if (last_dot != std::string::npos) filename = filename.substr(0, last_dot);
    
    // Strip secondary .tsp extension if it was .tsp.gz
    last_dot = filename.find_last_of('.');
    if (last_dot != std::string::npos && filename.substr(last_dot) == ".tsp") {
        filename = filename.substr(0, last_dot);
    }

    out_f << "NAME: " << filename << ".tour\n";
    out_f << "TYPE: TOUR\n";
    out_f << "DIMENSION: " << dimension << "\n";
    out_f << "TOUR_SECTION\n";
    
    for (int node : tour) {
        out_f << node << "\n";
    }
    
    out_f << "-1\n";
    out_f << "EOF\n";
    out_f.close();

    return 0;
}